"""Preserve successful native evidence and publish exact build/balance results locally."""
from pathlib import Path
import json,re,shutil,zipfile
ROOT=Path(__file__).resolve().parents[2]
def main():
 reports=ROOT/'tests/reports';r=json.loads((reports/'class-dragon-native.json').read_text());b=json.loads((reports/'production-build.json').read_text())
 assert r['passed'] and not r['failures'] and b['passed'] and b['package_success'] and not b['test_hooks']
 with zipfile.ZipFile(ROOT/b['archive']) as z:assert z.testzip() is None
 shutil.copyfile(reports/'production-build.json',reports/'class-dragon-build.json')
 work=ROOT/r['logs']
 for png in work.glob('*.png'):shutil.copyfile(png,reports/('class-dragon-'+png.name))
 archive=b['archive'].replace('\\','/');doc=ROOT/'CLASS_DRAGON_REPORT.md';s=doc.read_text(encoding='utf-8');placeholder='Aktuelle konkrete Runtime-Ergebnisse, Schadensmessungen, Kampfdauer und Produktionspaket werden nach Abschluss der laufenden nativen Prüfungen hier ergänzt. Frühere 322 PASS-Prüfungen und das Paket von 21:58 betreffen den vorangegangenen Stand, nicht diesen Umbau.'
 lines=[f'**PASS: {int(r["checks"])} native Prüfungen, Exitcode 0.** [Aktueller Windows-Produktionsbuild]({archive}), ohne Testinjektionen. ZIP-CRC vollständig geprüft. Projektintegrität: 897 Ressourcen, keine Probleme/Warnungen. [Native Ergebnisse](tests/reports/class-dragon-native.json), [Ressourcen-/Originalprüfung](tests/reports/class-dragon-assets.json), [Buildnachweis](tests/reports/class-dragon-build.json).','','Bossbasis auf 9.200 HP angepasst. Im normalen Room1 bei Minute fünf beträgt der bestehende Gegner-HP-Faktor 1,35, somit **12.420 tatsächliche Anfangs-HP**. Diese werden beim Spawn festgelegt und während des Kampfes nicht nach Schaden oder Build angepasst. Es gibt keine Mindestkampfdauer, Schadenssperre oder zeitabhängige Unverwundbarkeit.','','Die folgende Messung verwendet je Klasse 15 Fähigkeitsentscheidungen: Fireball/Lightning/Barrage Stufe 2, Healing Pulse Stufe 1; Power/Quick Hands Stufe 2, Keen Focus/Vitality/Wide Glyphs/Deep Rhythm Stufe 1. Echte Produktionswaffen, Projektile, kritische Treffer, Zauber und Passiven werden im nativen GameMaker ausgeführt. Der Boss dient als stationäres Ziel in 110 px Abstand. Das Angriffsfenster ist entweder ständig offen oder pro zehn Sekunden für sieben Sekunden offen; laufende Effekte können anschließend weiter treffen.','','| Klasse | gemessene DPS, volles Fenster | gemessene DPS, 70%-Fenster | HP/DPS-Prognose mit 70%-Fenster |']
 lines.append('|---|---|---|---|')
 for cls in ['Sword','Mage','Ranger']:
  full=next(v for v in r['metrics']['dps'] if v['class_name']==cls and v['variant']=='stationary_full_uptime');part=next(v for v in r['metrics']['dps'] if v['class_name']==cls and v['variant']=='scripted_70_percent_attack_uptime')
  lines.append(f'| {cls} | {full["dps"]:.2f} | {part["dps"]:.2f} | {part["estimated_seconds"]:.2f} s |')
 defeats=', '.join(f'{v["class_name"]} {v["measured_target_defeat_seconds"]:.2f} s' for v in r['metrics']['controlled_target_defeats'])
 perf=r['metrics']['performance']
 lines += ['',f'Zusätzlich gemessene Entleerung der 12.420 Ziel-HP bis zum letzten Treffer: **{defeats}**. Feindliche Rotation und Bewegung sind in diesen kontrollierten Messungen ausgeschaltet. Das sind gemessene Simulationszeiten gegen ein stationäres Ziel, kein menschlicher kompletter Bosskampf. Unterschiede zur HP/DPS-Prognose entstehen durch diskrete Kombos, laufende Effekte und kritische Treffer. Starke Builds dürfen schneller sein als 120 Sekunden.','',f'Kurze native Performance-Stichprobe mit {int(perf["enemies"])} Gegnern, Regen, KI und neuen Klassen-Effekten: {int(perf["frames"])} Frameintervalle, Mittel {perf["mean_frame_ms"]:.2f} ms, Maximum {perf["max_frame_ms"]:.2f} ms. PNG-Speicherung liegt außerhalb des Messfensters; kein Langzeitbenchmark.','','| Status | Tatsächlich geprüft |','|---|---|','| PASS | Viererfolge bis zum erneuten ersten Angriff, echte HP bei allen vier Schritten, einmalige Freigabe, keine Richtungswechsel-Resets |','| PASS | Zwölferschritte bis Schuss 13; exakt drei/fünf Pfeile auf 3/9, ein Pfeil auf 6 und 13, echter Pfeilhagelschaden |','| PASS | Unveränderte Schwerttreffer 11/13/19, unabhängige Waffen-/Zauberslots |','| PASS | Alle neun Drachenangriffe mit wirklichem HP-Verlust, Ende der Schadensphase, vier HP-Phasen und feste Rotationen, angekündigte Enrage-Kombinationen |','| PASS | Sprung über Bodenwelle, Slide unter erhöhtem Strahl, keine pauschale Sprungimmunität gegen Magma |','| PASS | Fünf Warnformen bei 0/25/50/75/100%; tatsächliche gefüllte Bildpixel zusätzlich gezählt, nicht nur Fortschrittszahlen |','| PASS | Kontakt beim Wechsel zu aktiv im gleichen Update bei 30/60/144 Hz; vor Vollendung kein Warnflächenschaden, Pause stoppt beides |','| PASS | Acht Richtungen, vorhandene Frame-Dateien, Ursprünge und neue Effekte, begrenzte/auslaufende Effektpools |','| PASS | 16 neue Audiodateien und tatsächlich erzeugte Audiostimmen auf getrennten nativen Spielframes; 70 WAVs technisch validiert |','| NOT RUN | Menschlicher 120–180-s-Bosskampf mit aktiver vollständiger Rotation |','| NOT RUN | Langzeit-Performance, manuelle Feinabnahme aller Animationsframes und subjektive Hörabnahme |','','Native Bilder: [Countdown 50%](tests/reports/class-dragon-warning-50.png), [Sternenorb](tests/reports/class-dragon-mage-star-flight.png), [Pfeilhagel](tests/reports/class-dragon-ranger-rain.png), [Drachenstrahl](tests/reports/class-dragon-dragon-beam-active.png). Weitere Warn-/Angriffsbilder liegen neben dem nativen JSON.','','Die früheren 322 Prüfungen gehören zum vorherigen Zaubersystem-Stand und werden hier nicht als neue Ergebnisse gezählt. Die neue Suite baut isoliert aus dem aktuellen Projekt und enthält keine automatisch bedienten Desktop-Eingaben. Fehlgeschlagene frühere Testläufe sind in ihren eigenen Logordnern erhalten; der finale PASS bezieht sich ausschließlich auf den oben verlinkten Lauf. Offen bleiben die genannten menschlichen Abnahmen und künstlerischen Detailverbesserungen. Keine bezahlte API, kein Git-Push.']
 if placeholder in s:s=s.replace(placeholder,'\n'.join(lines))
 else:s=re.sub(r'## Tests und Bossbalancing[\s\S]*','## Tests und Bossbalancing\n\n'+'\n'.join(lines)+'\n',s)
 doc.write_text(s,encoding='utf-8')
 p=ROOT/'README.md';s=p.read_text(encoding='utf-8');rows=s.splitlines();rows[2]=f'**Aktueller Stand:** [Zaubermeisterin, Waldläufer und Drachen-Countdown](CLASS_DRAGON_REPORT.md). {int(r["checks"])} native Prüfungen bestanden. [Aktueller Windows-Build]({archive}). [Zauberkatalog](SPELL_CATALOG.md). Frühere Berichte dokumentieren historische Zwischenstände.';p.write_text('\n'.join(rows)+'\n',encoding='utf-8')
 print('Published successful local report/build evidence:',archive)
if __name__=='__main__':main()
